client_script:
frappe.web_form.after_load = function() {
  var doc = frappe.web_form.doc;
  if (doc && doc.name) {
    var refEl = document.createElement('div');
    refEl.innerHTML = '<div style="margin-bottom:12px;padding:8px 16px;background:#e3f2fd;color:#1565c0;border-left:4px solid #1976d2;border-radius:6px;display:inline-block;font-weight:700;font-size:14px;">Réf. : ' + doc.name + '</div>';
    var w = document.querySelector('.web-form-wrapper') || document.querySelector('.container');
    if (w) w.prepend(refEl);
  }
  var roles = (frappe.boot && frappe.boot.user && frappe.boot.user.roles) ? frappe.boot.user.roles : [];
  var state = (doc && (doc.workflow_state || doc.statut)) || 'Brouillon';
  // Masquer la signature DG par défaut, l'activer seulement quand workflow=En attente DG
  frappe.web_form.set_df_property('signature_dg', 'read_only', 1);
  if (state === 'En attente DG' && (roles.indexOf('Directeur Général') !== -1 || roles.indexOf('System Manager') !== -1)) {
    frappe.web_form.set_df_property('signature_dg', 'read_only', 0);
  }
  if (doc && doc.statut) {
    var cm = {'Approuv\u00e9':'#2e7d32','Rejet\u00e9':'#c62828','Brouillon':'#757575'};
    var c = cm[doc.statut] || '#1565c0';
    var el = document.createElement('div');
    el.innerHTML = '<div style="margin-bottom:12px;padding:8px 16px;background:'+c+';color:#fff;border-radius:6px;display:inline-block;font-weight:700;">\u00c9tat\u00a0: '+doc.statut+'</div>';
    var w2 = document.querySelector('.web-form-wrapper') || document.querySelector('.container');
    if (w2) w2.prepend(el);
  }
};
